def row_marker(record: dict, expected: dict, expected_digest: str) -> str:
    if record["identity"] == expected["identity"] and record["ref"] == expected["ref"] and record["commit"] == expected["commit"] and record["flag_a"] is True and record["flag_b"] is True and record["digest"] == expected_digest:
        return "="
    return "!"

